questionvariables.text:
/* Design: choose a method for each situation, one dropdown per row. Situations 1-3 counting squares (C), 4-6 trapezoidal (T: odd numbers of strips, so the mid-ordinate rule cannot use them), 7-9 mid-ordinate (M: no edge values). Every selection has all three methods. Source: original. */
SIT: ["An aerial photograph of a forest with a grid of squares printed over it. No measurements were made on the ground.",
      "The outline of a footprint drawn round on centimetre squared paper.",
      "The shadow of a tree on a playground marked out in squares of 1 m by 1 m.",
      "The depth of an irrigation canal 3.5 m wide, measured at both edges and every 0.5 m across.",
      "The width of a school garden measured at both ends and every 4 m along a straight path 20 m long.",
      "The heights of a curve known at x = 0, 1, 2, 3, 4 and 5 only.",
      "The width of a tea plot measured only at 10 m, 30 m and 50 m along a straight track 60 m long.",
      "The height of a rock face measured at the middle of each 5 m section along its foot, and nowhere else.",
      "The height of a curved hedge measured at the centre of each 2 m section along a 12 m path."];
MTH: ["C","C","C","T","T","T","M","M","M"];
SEL: [[1,4,7,5],[2,5,8,9],[3,6,7,1],[4,9,2,6],[5,1,8,3],[6,7,2,4],[7,3,5,8],[8,2,6,1],[9,4,3,5],[1,8,6,9]];
ix: 1+rand(10);
rows: SEL[ix];
mr: makelist(MTH[rows[j]],j,1,4);
s1: SIT[rows[1]]; s2: SIT[rows[2]]; s3: SIT[rows[3]]; s4: SIT[rows[4]];
mk(m) := [["none",false,"none of these: the area cannot be estimated"],["cs",is(m="C"),"counting squares"],["tr",is(m="T"),"the trapezoidal rule"],["mo",is(m="M"),"the mid-ordinate rule"]];
o1: mk(mr[1]); o2: mk(mr[2]); o3: mk(mr[3]); o4: mk(mr[4]);
kv: makelist(if mr[j]="C" then "cs" elseif mr[j]="T" then "tr" else "mo",j,1,4);
/* test inputs */
t2v: makelist(if mr[j]="C" then "cs" elseif mr[j]="T" then "mo" else "tr",j,1,4);
t3v: makelist(if mr[j]="C" then "tr" else kv[j],j,1,4);
ft: first(sublist_indices(mr, lambda([m], m="T")));
nonev: makelist(if j=ft then "none" else kv[j],j,1,4);

feedbackvariables.text:
aa: [ans1,ans2,ans3,ans4];
tms: some(lambda([j], (mr[j]="T" and aa[j]="mo") or (mr[j]="M" and aa[j]="tr")), [1,2,3,4]);
csw: some(lambda([j], (mr[j]="C" and aa[j]#"cs") or (mr[j]#"C" and aa[j]="cs")), [1,2,3,4]);
nc: length(sublist([1,2,3,4], lambda([j], aa[j]=kv[j])));
rcl: makelist(if aa[j]=kv[j] then 0 elseif aa[j]="none" then 1 elseif aa[j]="cs" then 2 elseif mr[j]="C" then 3 elseif aa[j]="tr" then 4 else 5, j, 1, 4);
rc1: rcl[1]; rc2: rcl[2]; rc3: rcl[3]; rc4: rcl[4];
RDT: ["", "", "", "Here the depths are at both edges and every 0.5 m between: they are the edges of 7 strips, and 7 strips cannot be paired into wider ones.", "Here the widths are at both ends and every 4 m between: they are the edges of 5 strips, and 5 strips cannot be paired into wider ones.", "Here the heights are at x = 0, 1, 2, 3, 4 and 5: they are the edges of 5 strips, and 5 strips cannot be paired into wider ones.", "Here the width was not measured at 0 m or at 60 m.", "Here the height was measured only at the middle of each section, not at the ends of the sections.", "Here the height was measured only at the centre of each section, not at the ends of the sections."];
rd1: RDT[rows[1]]; rd2: RDT[rows[2]]; rd3: RDT[rows[3]]; rd4: RDT[rows[4]];
